def build_request(user_text, system="You are helpful.", temperature=0.7):
    return {
        "model": "some-model",
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": user_text},
        ],
        "temperature": temperature,
    }
r = build_request("Hi", temperature=0)
print(r["messages"][0]["content"], r["temperature"])  # You are helpful. 0
Defaults keep everyday calls short; keyword arguments override one setting.

