calls = []
def flaky_model(messages):
    calls.append(1)
    if len(calls) == 1:
        raise ConnectionError("network down")
    return fake_model(messages)

def call_with_retry(model_fn, messages, tries=3):
    for attempt in range(tries):
        try:
            return model_fn(messages)
        except ConnectionError:
            print("retrying")
    raise RuntimeError("model unavailable")

data = call_with_retry(flaky_model, [])
print(len(calls))  # retrying, then 2
Fakes can fail on purpose, so error paths get tested without waiting for a real outage.

weather_tool = {
    "type": "function",
    "function": {
        "name": "get_weather",
        "description": "Get the current temperature for a city.",
        "parameters": {
            "type": "object",
            "properties": {"city": {"type": "string", "description": "City name"}},
