def one_step(model_fn, messages):
    message = model_fn(messages)["choices"][0]["message"]
    messages.append(message)
    if not message.get("tool_calls"):
        return message["content"]
    return None

def done_model(messages):
    return text_reply("Done.")

print(one_step(done_model, []))  # Done.
A text answer means the agent has finished; None here means 'tools still to run'.

