def check_runnable(working_dir, file_path):
    target = resolve(working_dir, file_path)
    if target is None:
        return f'Error: "{file_path}" is outside the working directory'
    if not file_path.endswith(".py"):
        return f'Error: "{file_path}" is not a Python file'
    return None

print(check_runnable("calculator", "pkg/big.txt"))  # Error: "pkg/big.txt" is not a Python file
Reuse resolve() from sandboxed_file_tools; refuse anything else before running.

def format_result(result):
    parts = []
    if result.stdout:
        parts.append("STDOUT: " + result.stdout)
    if result.stderr:
        parts.append("STDERR: " + result.stderr)
    if result.returncode != 0:
        parts.append(f"Process exited with code {result.returncode}")
    return "\n".join(parts) or "No output produced."
The model needs everything that happened (output, errors, exit code) in plain text; an empty result still says so.

