@dataclass
class TextNode:
    text: str
    text_type: TextType
    url: str | None = None

    def __repr__(self):
        return f"({self.text_type.value}: {self.text})"

print(TextNode("hi", TextType.BOLD) == TextNode("hi", TextType.BOLD))  # True
print([TextNode("a ", TextType.TEXT), TextNode("b", TextType.CODE)])  # [(text: a ), (code: b)]
@dataclass writes __eq__ for you; a short __repr__ (which the dataclass keeps) makes lists of nodes easy to read in test failures.

nodes = []
for i, part in enumerate("a `b` c".split("`")):
    if part != "" and i % 2 == 0:
        nodes.append(TextNode(part, TextType.TEXT))
    elif part != "":
        nodes.append(TextNode(part, TextType.CODE))
print(nodes)  # [(text: a ), (code: b), (text:  c)]
Even index -> plain text, odd index -> the delimiter's type; empty pieces are skipped.

def split_nodes_delimiter(old_nodes, delimiter, text_type):
    new_nodes = []
    for node in old_nodes:
        if node.text_type != TextType.TEXT:
            new_nodes.append(node)
        else:
            parts = node.text.split(delimiter)
            if len(parts) % 2 == 0:
                raise ValueError(f"unmatched {delimiter} in: {node.text}")
            for i, part in enumerate(parts):
                if part != "" and i % 2 == 0:
                    new_nodes.append(TextNode(part, TextType.TEXT))
                elif part != "":
                    new_nodes.append(TextNode(part, text_type))
    return new_nodes

nodes = [TextNode("**a** b", TextType.TEXT), TextNode("x", TextType.CODE)]
print(split_nodes_delimiter(nodes, "**", TextType.BOLD))  # [(bold: a), (text:  b), (code: x)]
Nodes that are already code, bold, links... pass through untouched; call once per delimiter (**, _, `).

import re

def extract_markdown_images(text):
    return re.findall(r"!\[([^\[\]]*)\]\(([^\(\)]*)\)", text)

def extract_markdown_links(text):
    return re.findall(r"(?<!!)\[([^\[\]]*)\]\(([^\(\)]*)\)", text)

assert extract_markdown_images("![a](b.png) [c](d)") == [("a", "b.png")]
assert extract_markdown_links("![a](b.png) [c](d)") == [("c", "d")]
print("ok")  # ok
Named functions hide the unreadable patterns; asserts pin down their behaviour.

def split_nodes_image(old_nodes):
    new_nodes = []
    for node in old_nodes:
        if node.text_type != TextType.TEXT:
            new_nodes.append(node)
        else:
            text = node.text
            for alt, url in extract_markdown_images(text):
                before, text = text.split(f"![{alt}]({url})", 1)
                if before:
                    new_nodes.append(TextNode(before, TextType.TEXT))
                new_nodes.append(TextNode(alt, TextType.IMAGE, url))
            if text:
                new_nodes.append(TextNode(text, TextType.TEXT))
    return new_nodes

print(split_nodes_image([TextNode("a ![x](1.png) b ![y](2.png)", TextType.TEXT)]))
# [(text: a ), (image: x), (text:  b ), (image: y)]
After each match the remainder is searched again; empty text before or after is skipped.

def markdown_to_blocks(markdown):
    blocks = []
    for block in markdown.split("\n\n"):
        block = block.strip()
        if block != "":
            blocks.append(block)
    return blocks

print(markdown_to_blocks("# A\n\n\n\nB  \n"))  # ['# A', 'B']
Extra blank lines create empty or whitespace-only pieces; strip them and skip the empties.

def is_heading(block):
    return block.startswith(("# ", "## ", "### ", "#### ", "##### ", "###### "))

print(is_heading("### Notes"), is_heading("#Notes"), is_heading("####### x"))  # True False False
startswith accepts a tuple of prefixes; the space after the # is required.

def every_line_starts_with(block, prefix):
    for line in block.split("\n"):
        if not line.startswith(prefix):
            return False
    return True

print(every_line_starts_with("- a\n- b", "- "), every_line_starts_with("- a\nb", "- "))  # True False
One line without the marker makes the block a paragraph; return False at the first failure.

def is_ordered_list(block):
    number = 1
    for line in block.split("\n"):
        if not line.startswith(f"{number}. "):
            return False
        number += 1
    return True

print(is_ordered_list("1. a\n2. b"), is_ordered_list("1. a\n3. b"))  # True False
Each line must carry the next number; with this, block_to_block_type tries heading, code, quote, lists, else paragraph.

class LeafNode(HTMLNode):
    def __init__(self, tag, value, props=None):
        super().__init__(tag, value, None, props)

leaf = LeafNode("b", "bold")
print(leaf.value, leaf.children)  # bold None
A leaf never has children, so its constructor does not take any and passes None up.

class LeafNode(HTMLNode):
    def __init__(self, tag, value, props=None):
        super().__init__(tag, value, None, props)

    def to_html(self):
        if self.value is None:
            raise ValueError("a leaf node needs a value")
        if self.tag is None:
            return self.value
        return f"<{self.tag}{self.props_to_html()}>{self.value}</{self.tag}>"

print(LeafNode("a", "Docs", {"href": "/docs"}).to_html())  # <a href="/docs">Docs</a>
The opening tag carries the props; the closing tag repeats the tag name with a /.

class ParentNode(HTMLNode):
    def __init__(self, tag, children, props=None):
        super().__init__(tag, None, children, props)

    def to_html(self):
        if self.tag is None:
            raise ValueError("a parent node needs a tag")
        if not self.children:
            raise ValueError("a parent node needs children")
        inner = ""
        for child in self.children:
            inner += child.to_html()
        return f"<{self.tag}{self.props_to_html()}>{inner}</{self.tag}>"

p = ParentNode("p", [LeafNode("b", "Hi"), LeafNode(None, " there")])
print(p.to_html())  # <p><b>Hi</b> there</p>
Each child renders itself; the parent only adds its own opening and closing tags.

def text_node_to_html_node(node):
    match node.text_type:
        case TextType.TEXT:
            return LeafNode(None, node.text)
        case TextType.BOLD:
            return LeafNode("b", node.text)
        case TextType.ITALIC:
            return LeafNode("i", node.text)
        case TextType.CODE:
            return LeafNode("code", node.text)

print(text_node_to_html_node(TextNode("x", TextType.BOLD)).to_html())  # <b>x</b>
match compares the enum member against each case in turn.

        case TextType.LINK:
            return LeafNode("a", node.text, {"href": node.url})
        case TextType.IMAGE:
            return LeafNode("img", "", {"src": node.url, "alt": node.text})
# <a href="/">home</a>   <img src="c.png" alt="cat"></img>
An image has no inner text, so its value is "" and the TextNode's text becomes the alt attribute.

import os, shutil
def copy_tree(src, dst):
    os.makedirs(dst, exist_ok=True)
    for name in sorted(os.listdir(src)):
        src_path = os.path.join(src, name)
        dst_path = os.path.join(dst, name)
        if os.path.isfile(src_path):
            shutil.copy(src_path, dst_path)
        else:
            copy_tree(src_path, dst_path)

copy_tree("static", "public")
print(os.listdir("public/images"))  # ['logo.png']
A folder is a tree: files are leaves (copy them), folders are subtrees (call copy_tree again).

def extract_title(markdown):
    for line in markdown.split("\n"):
        if line.startswith("# "):
            return line[2:].strip()
    raise ValueError("no h1 heading")

print(extract_title("Intro\n# My Site \ntext"))  # My Site
Only '# ' (one # and a space) counts; a page without one is an error, not a blank title.

def fill(template, title, content):
    return template.replace("{{ Title }}", title).replace("{{ Content }}", content)

print(fill("<title>{{ Title }}</title>{{ Content }}", "Home", "<p>Hi</p>"))
# <title>Home</title><p>Hi</p>
replace returns a new string, so the two calls are chained; template engines like Jinja do the same job with more features.

def generate_all(src_dir, template_path, dst_dir):
    for name in sorted(os.listdir(src_dir)):
        src = os.path.join(src_dir, name)
        if os.path.isfile(src) and name.endswith(".md"):
            generate_page(src, template_path, os.path.join(dst_dir, name[:-3] + ".html"))
        elif not os.path.isfile(src):
            generate_all(src, template_path, os.path.join(dst_dir, name))

generate_all("content", "template.html", "public")
print(sorted(os.listdir("public")), os.listdir("public/blog"))  # ['blog', 'index.html'] ['first.html']
Same recursion as copy_tree; content/blog/first.md becomes public/blog/first.html.

def main():
    if os.path.exists("public"):
        shutil.rmtree("public")
    copy_tree("static", "public")
    generate_all("content", "template.html", "public")
Clean, copy, generate: every build starts from nothing, so the output always matches the sources.
